pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }
    function testRegression_property() public {
        Reverter reverter = new Reverter();
        address[] memory tos = new address[](1);
        tos[0] = address(0xdead);
        bool ok;
        try c.transfer(address(this), address(reverter), tos, 1) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert("always revert");
    }
}
